const NL = String.fromCharCode(10);
const BT = String.fromCharCode(96);
const esc = (s) => s.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');

function emojiFor(h) {
  const t = h.toLowerCase();
  if (t.includes('what happened')) return '🔎 ';
  if (t.includes('key facts')) return '📌 ';
  if (t.includes('why')) return '💡 ';
  if (t.includes('impact')) return '📊 ';
  if (t.includes('risk')) return '⚠️ ';
  if (t.includes('takeaway')) return '✅ ';
  return '';
}

function format(text) {
  let titleNext = false;
  const lines = text.split(NL).map((raw) => {
    let line = raw.trim();
    if (!line) return '';
    let heading = false;
    const h = line.match(/^#+ *(.+)$/);
    const b = line.match(/^[*][*](.+?)[*][*]:?$/);
    if (h) {
      line = h[1];
      heading = true;
    } else if (b) {
      line = b[1];
      heading = true;
    } else if (/^[-*•] +/.test(line)) {
      line = '• ' + line.replace(/^[-*•] +/, '');
    }
    line = line.split('*').join('').split('#').join('').split(BT).join('').split('~').join('').trim();
    if (heading && line.toLowerCase() === 'headline') {
      titleNext = true;
      return null;
    }
    const safe = esc(line);
    if (titleNext && !heading) {
      titleNext = false;
      return '<b><u>📰 ' + safe + '</u></b>' + NL;
    }
    if (heading) return NL + '<b>' + emojiFor(line) + safe + '</b>';
    return safe;
  }).filter((l) => l !== null);
  let out = lines.join(NL);
  while (out.includes(NL + NL + NL)) out = out.split(NL + NL + NL).join(NL + NL);
  return out.trim();
}

const parts = $input.all()
  .map((i) => i.json.output)
  .filter((o) => typeof o === 'string' && o.trim().length > 0)
  .map(format);

if (parts.length === 0) return [];

const combined = parts.join(NL + NL + '━━━━━━━━━━━━━━' + NL + NL);
if (combined.length <= 4096) {
  return [{ json: { telegram_message: combined } }];
}

return parts.map((p) => ({ json: { telegram_message: p } }));
